14: func TestManagementAuthorityCancelsCommittedWriteAndRecoversFromSnapshot(t *testing.T) {
15: 	for _, stage := range []string{"response headers", "response body"} {
16: 		t.Run(stage, func(t *testing.T) {
17: 			f := newFakeManager(t)
18: 			var leader, interrupt atomic.Bool
19: 			leader.Store(true)
20: 			interrupt.Store(true)
21: 			cancelled := make(chan struct{})
22: 			server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
23: 				if r.Method == http.MethodPost && r.URL.Path == "/api/groups" && interrupt.CompareAndSwap(true, false) {
24: 					// Commit externally, but lose the response as authority transfers.
25: 					f.serve(httptest.NewRecorder(), r)
26: 					if stage == "response body" {
27: 						w.Header().Set("Content-Length", "100")
28: 						w.WriteHeader(http.StatusCreated)
29: 						_, _ = w.Write([]byte("{"))
30: 						w.(http.Flusher).Flush()
31: 					}
32: 					leader.Store(false)
33: 					<-r.Context().Done()
34: 					close(cancelled)
35: 					return
36: 				}
37: 				f.serve(w, r)
38: 			}))
39: 			t.Cleanup(server.Close)
40: 			loop := Loop{Leader: leader.Load, Desired: GRU(), ManagementURL: server.URL,
41: 				Token: func(context.Context) ([]byte, error) { return []byte(testPAT), nil }}.withDefaults()
42: 			ctx, cancel := context.WithTimeout(t.Context(), 5*time.Second)
43: 			defer cancel()
44: 			var tokenReads atomic.Int32
45: 			follower := Loop{ManagementURL: server.URL, Desired: GRU(), Token: func(context.Context) ([]byte, error) {
46: 				tokenReads.Add(1)
47: 				return []byte(testPAT), nil
48: 			}}.withDefaults()
49: 			if err := follower.cycle(ctx, map[string]bool{}); !errors.Is(err, errAuthorityLost) {
50: 				t.Fatalf("missing authority did not refuse cycle: %v", err)
51: 			}
52: 			followerCtx, stopFollower := context.WithTimeout(ctx, 20*time.Millisecond)
53: 			Loop{initialDelay: time.Millisecond, Interval: time.Millisecond}.Run(followerCtx)
54: 			stopFollower()
55: 			if tokenReads.Load() != 0 || len(f.mutations) != 0 {
56: 				t.Fatal("missing authority read credentials or mutated the manager")
57: 			}
58: 			if err := loop.cycle(ctx, map[string]bool{}); !errors.Is(err, errAuthorityLost) {
59: 				t.Fatalf("authority transfer did not cancel active request: %v", err)
60: 			}
61: 			select {
62: 			case <-cancelled:
63: 			case <-ctx.Done():
64: 				t.Fatal("external request did not observe cancellation")
65: 			}
66: 			if len(f.groups) != 1 || len(f.mutations) != 1 {
67: 				t.Fatalf("stale cycle continued after committed write: groups=%d mutations=%v", len(f.groups), f.mutations)
68: 			}
69: 			createdID := f.groups[0].ID
70: 			leader.Store(true)
71: 			if err := loop.cycle(ctx, map[string]bool{}); err != nil {
72: 				t.Fatal(err)
73: 			}
74: 			if len(f.groups) != len(GRU().Groups) || f.groups[0].ID != createdID {
75: 				t.Fatalf("recovery duplicated or replaced committed identity: %+v", f.groups)
76: 			}
77: 			f.mutations = nil
78: 			if err := loop.cycle(ctx, map[string]bool{}); err != nil || len(f.mutations) != 0 {
79: 				t.Fatalf("recovered manager did not converge: %v %v", err, f.mutations)
80: 			}
81: 		})
82: 	}
83: }

