56: func TestAutomaticAccountAuthorityRecoversAcrossOwnerRestart(t *testing.T) {
57: 	for _, response := range []string{"returned", "lost"} {
58: 		t.Run(response, func(t *testing.T) {
59: 			ctx, cancel := context.WithTimeout(t.Context(), 10*time.Second)
60: 			defer cancel()
61: 			js, _ := accountAuthorityStore(t)
62: 			first, err := authority.Start(ctx, js, accountAuthorityConfig("gru"))
63: 			if err != nil {
64: 				t.Fatal(err)
65: 			}
66: 			fencer := &accountAuthority{}
67: 			fencer.current.Store(first)
68: 			t.Cleanup(func() { _ = fencer.current.Load().Close() })
69: 			f := newFakeManager(t)
70: 			var interrupt atomic.Bool
71: 			interrupt.Store(true)
72: 			handoff := make(chan error, 1)
73: 			api := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
74: 				if r.Method == http.MethodPost && r.URL.Path == "/api/groups" && interrupt.CompareAndSwap(true, false) {
75: 					committed := httptest.NewRecorder()
76: 					f.serve(committed, r)
77: 					if err := first.Close(); err != nil {
78: 						handoff <- err
79: 						w.WriteHeader(http.StatusInternalServerError)
80: 						return
81: 					}
82: 					next, err := authority.Start(ctx, js, accountAuthorityConfig("gru"))
83: 					if err != nil {
84: 						handoff <- err
85: 						w.WriteHeader(http.StatusInternalServerError)
86: 						return
87: 					}
88: 					fencer.current.Store(next)
89: 					handoff <- nil
90: 					if response == "lost" {
91: 						<-r.Context().Done()
92: 						return
93: 					}
94: 					w.WriteHeader(committed.Code)
95: 					_, _ = w.Write(committed.Body.Bytes())
96: 					return
97: 				}
98: 				f.serve(w, r)
99: 			}))
100: 			t.Cleanup(api.Close)
101: 			loop := Automatic(fencer, nil, nil).withDefaults()
102: 			loop.ManagementURL = api.URL
103: 			loop.Token = func(context.Context) ([]byte, error) { return []byte(testPAT), nil }
104: 			if err := loop.cycle(ctx, map[string]bool{}); !errors.Is(err, errAuthorityLost) {
105: 				t.Fatalf("old owner continued across restart: %v", err)
106: 			}
107: 			if err := <-handoff; err != nil {
108: 				t.Fatal(err)
109: 			}
110: 			if len(f.groups) != 1 || len(f.mutations) != 1 {
111: 				t.Fatalf("old owner wrote after handoff: groups=%d writes=%v", len(f.groups), f.mutations)
112: 			}
113: 			created := f.groups[0].ID
114: 			if err := loop.cycle(ctx, map[string]bool{}); err != nil {
115: 				t.Fatal(err)
116: 			}
117: 			if f.groups[0].ID != created || len(f.groups) != len(GRU().Groups) {
118: 				t.Fatal("new owner did not recover the committed group identity")
119: 			}
120: 			f.mutations = nil
121: 			if err := loop.cycle(ctx, map[string]bool{}); err != nil || len(f.mutations) != 0 {
122: 				t.Fatalf("recovered account did not converge: %v %v", err, f.mutations)
123: 			}
124: 		})
125: 	}
126: }

