24: func TestEnrollmentRecoversCommittedResponsesAndDelivery(t *testing.T) {
25: 	for _, interruption := range []string{"key-response", "vault-response", "before-key-dispatch"} {
26: 		t.Run(interruption, func(t *testing.T) {
27: 			root := t.TempDir()
28: 			keyPath, vaultPath := filepath.Join(root, "upstream.json"), filepath.Join(root, "vault.json")
29: 			const keyValue = "884B8BCF-16BC-4D2C-8A3F-AE5F8B6B3BA3"
30: 			const secretID = "ocid1.vaultsecret.oc1.sa-saopaulo-1.test.enrollment"
31: 			var interrupted atomic.Bool
32: 			var keysCreated, vaultsCreated atomic.Int32
33: 			var term atomic.Uint64
34: 			term.Store(1)
35: 			managerServer := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
36: 				if r.Header.Get("Authorization") != "Token "+testPAT {
37: 					http.Error(w, "unauthorized", http.StatusUnauthorized)
38: 					return
39: 				}
40: 				keys := readEnrollmentJSON[[]apiSetupKey](t, keyPath)
41: 				switch {
42: 				case r.Method == http.MethodGet && r.URL.Path == "/api/groups":
43: 					writeEnrollmentJSON(t, w, []apiGroup{{ID: "servers", Name: "gru-servers", Issued: "api"}})
44: 				case r.Method == http.MethodGet && r.URL.Path == "/api/setup-keys":
45: 					if keys == nil {
46: 						keys = []apiSetupKey{}
47: 					}
48: 					writeEnrollmentJSON(t, w, keys)
49: 				case r.Method == http.MethodPost && r.URL.Path == "/api/setup-keys":
50: 					var request setupKeyRequest
51: 					if err := json.UnmarshalRead(r.Body, &request); err != nil {
52: 						t.Error(err)
53: 						w.WriteHeader(http.StatusBadRequest)
54: 						return
55: 					}
56: 					id := fmt.Sprintf("key-%d", keysCreated.Add(1))
57: 					keys = append(keys, apiSetupKey{ID: id, Name: request.Name, Type: request.Type,
58: 						State: "valid", Valid: true, AutoGroups: request.AutoGroups})
59: 					persistEnrollmentJSON(t, keyPath, keys)
60: 					if interruption == "key-response" && interrupted.CompareAndSwap(false, true) {
61: 						w.WriteHeader(http.StatusServiceUnavailable)
62: 						return
63: 					}
64: 					writeEnrollmentJSON(t, w, map[string]string{"id": id, "key": keyValue})
65: 				case r.Method == http.MethodPut && strings.HasPrefix(r.URL.Path, "/api/setup-keys/"):
66: 					var request struct {
67: 						Revoked bool `json:"revoked"`
68: 					}
69: 					if err := json.UnmarshalRead(r.Body, &request); err != nil || !request.Revoked {
70: 						t.Errorf("invalid targeted revocation: %v", err)
71: 					}
72: 					id := strings.TrimPrefix(r.URL.Path, "/api/setup-keys/")
73: 					for i := range keys {
74: 						if keys[i].ID == id {
75: 							keys[i].Revoked, keys[i].Valid, keys[i].State = true, false, "revoked"
76: 						}
77: 					}
78: 					persistEnrollmentJSON(t, keyPath, keys)
79: 					w.WriteHeader(http.StatusNoContent)
80: 				default:
81: 					t.Errorf("unexpected NetBird request %s %s", r.Method, r.URL.Path)
82: 					w.WriteHeader(http.StatusBadRequest)
83: 				}
84: 			}))
85: 			t.Cleanup(managerServer.Close)
86: 			factory, endpoint := ociresourcetest.Server(t, func(w http.ResponseWriter, r *http.Request) {
87: 				stored := readEnrollmentJSON[map[string]any](t, vaultPath)
88: 				w.Header().Set("Content-Type", "application/json")
89: 				switch {
90: 				case r.Method == http.MethodPost && strings.Contains(r.URL.Path, "secretbundles/actions/getByName"):
91: 					if stored == nil {
92: 						w.WriteHeader(http.StatusNotFound)
93: 						writeEnrollmentJSON(t, w, map[string]string{"code": "SecretNotFound", "message": "absent"})
94: 						return
95: 					}
96: 					writeEnrollmentJSON(t, w, map[string]any{"secretId": secretID, "versionNumber": 1,
97: 						"secretBundleContent": map[string]string{"contentType": "BASE64", "content": stored["content"].(string)}})
98: 				case r.Method == http.MethodGet && strings.HasSuffix(r.URL.Path, "/secrets"):
99: 					items := []map[string]any{}
100: 					if stored != nil {
101: 						items = append(items, map[string]any{"id": secretID, "secretName": stored["name"], "lifecycleState": "ACTIVE"})
102: 					}
103: 					writeEnrollmentJSON(t, w, items)
104: 				case r.Method == http.MethodPost && strings.HasSuffix(r.URL.Path, "/secrets"):
105: 					var request struct {
106: 						SecretName    string `json:"secretName"`
107: 						SecretContent struct {
108: 							Content string `json:"content"`
109: 						} `json:"secretContent"`
110: 					}
111: 					if err := json.UnmarshalRead(r.Body, &request); err != nil {
112: 						t.Error(err)
113: 						return
114: 					}
115: 					if r.Header.Get("opc-retry-token") == "" {
116: 						t.Error("Vault create lacks retry identity")
117: 					}
118: 					decoded, err := base64.StdEncoding.DecodeString(request.SecretContent.Content)
119: 					if err != nil || string(decoded) != keyValue {
120: 						t.Error("Vault delivery differs from escrow")
121: 						w.WriteHeader(http.StatusBadRequest)
122: 						return
123: 					}
124: 					vaultsCreated.Add(1)
125: 					persistEnrollmentJSON(t, vaultPath, map[string]any{"name": request.SecretName, "content": request.SecretContent.Content})
126: 					if interruption == "vault-response" && interrupted.CompareAndSwap(false, true) {
127: 						w.WriteHeader(http.StatusBadRequest)
128: 						writeEnrollmentJSON(t, w, map[string]string{"code": "Interrupted", "message": "response lost after commit"})
129: 						return
130: 					}
131: 					writeEnrollmentJSON(t, w, map[string]string{"id": secretID})
132: 				default:
133: 					t.Errorf("unexpected Vault request %s %s", r.Method, r.URL.Path)
134: 					w.WriteHeader(http.StatusBadRequest)
135: 				}
136: 			})
137: 			management, err := ocivault.NewVaultsClientWithConfigurationProvider(factory.Provider())
138: 			if err != nil {
139: 				t.Fatal(err)
140: 			}
141: 			factory.Configure(&management.BaseClient, ociclient.ServiceVault)
142: 			management.Host = endpoint
143: 			bundles, err := vaultsecret.SecretsClient(factory)
144: 			if err != nil {
145: 				t.Fatal(err)
146: 			}
147: 			bundles.Host = endpoint
148: 			vault := EnrollmentVault{Target: vaultsecret.Target{CompartmentID: "ocid1.compartment.oc1..control", VaultID: "ocid1.vault.oc1.sa-saopaulo-1.enrollment", KeyID: "ocid1.key.oc1.sa-saopaulo-1.enrollment"}, Management: management, Bundles: bundles, Name: "gru-1-netbird-setup-key"}
149: 			stateDir := filepath.Join(root, "protected", "enrollment")
150: 			reconcile := func() (EnrollmentResult, error) {
151: 				api, err := NewAPI(managerServer.URL, testPAT)
152: 				if err != nil {
153: 					return EnrollmentResult{}, err
154: 				}
155: 				defer api.Close()
156: 				expected := term.Load()
157: 				api.beforeWrite = func() error {
158: 					if interruption == "before-key-dispatch" && interrupted.CompareAndSwap(false, true) {
159: 						term.Add(1)
160: 					}
161: 					if term.Load() != expected {
162: 						return errAuthorityLost
163: 					}
164: 					return nil
165: 				}
166: 				return ReconcileServerEnrollment(t.Context(), api, GRU(), stateDir, vault, EnrollmentAuthority{Check: func() error {
167: 					if term.Load() != expected {
168: 						return errAuthorityLost
169: 					}
170: 					return nil
171: 				}, Quiesce: func(context.Context) error { return nil }})
172: 			}
173: 			first, firstErr := reconcile()
174: 			if interruption != "vault-response" && firstErr == nil {
175: 				t.Fatalf("interruption claimed success: %+v", first)
176: 			}
177: 			result, err := reconcile()
178: 			if err != nil || result.SecretID != secretID || result.KeyID == "" {
179: 				t.Fatalf("restart did not recover delivery: %+v %v", result, err)
180: 			}
181: 			wantCreates := int32(1)
182: 			if interruption == "key-response" {
183: 				wantCreates = 2
184: 			}
185: 			if keysCreated.Load() != wantCreates || vaultsCreated.Load() != 1 {
186: 				t.Fatalf("duplicate credentials: keys=%d vaults=%d", keysCreated.Load(), vaultsCreated.Load())
187: 			}
188: 			again, err := reconcile()
189: 			if err != nil || again != result || keysCreated.Load() != wantCreates || vaultsCreated.Load() != 1 {
190: 				t.Fatalf("delivered identity changed: %+v %v", again, err)
191: 			}
192: 			keys := readEnrollmentJSON[[]apiSetupKey](t, keyPath)
193: 			if interruption == "key-response" && (!keys[0].Revoked || keys[1].Revoked) {
194: 				t.Fatal("orphan recovery revoked the delivered key")
195: 			}
196: 			info, err := os.Stat(filepath.Join(stateDir, "enrollment.json"))
197: 			if err != nil || info.Mode().Perm() != 0600 {
198: 				t.Fatal("escrow is not protected")
199: 			}
200: 		})
201: 	}
202: }

