33: func TestPodmanManagerSyncAndPrune(t *testing.T) {
34: 	if os.Getenv("TS_NETBIRD_PODMAN") != "1" {
35: 		t.Skip("set TS_NETBIRD_PODMAN=1 to run the NetBird manager Podman integration test")
36: 	}
37: 	if _, err := exec.LookPath("podman"); err != nil {
38: 		t.Skip("podman is not installed; the NetBird manager integration test needs it")
39: 	}
40: 	ctx, cancel := context.WithTimeout(t.Context(), 12*time.Minute)
41: 	defer cancel()
42: 	stack := newPodmanStack(ctx, t)
43: 	owner := stack.startServer()
44: 
45: 	// The PAT belongs to a dedicated service user with the admin role, the
46: 	// least-privileged built-in role able to do everything sync and prune do.
47: 	admin := stack.serviceUserToken(owner, "ts-orchestrator", "admin")
48: 	networkAdmin := stack.serviceUserToken(owner, "network-admin-probe", "network_admin")
49: 
50: 	seeded := stack.seedLegacy(owner)
51: 	d := GRU()
52: 	// Slot addresses become this test network's fixed container IPs, inside
53: 	// the test cell subnet as Validate requires.
54: 	d.Network.Resource.Address = stack.cellSubnet()
55: 	for i := range d.Slots {
56: 		d.Slots[i].IP = stack.slotIP(d.Slots[i].IP)
57: 	}
58: 	api, err := NewAPI(stack.base, admin)
59: 	if err != nil {
60: 		t.Fatal(err)
61: 	}
62: 	defer api.Close()
63: 
64: 	if _, err := Prune(ctx, api, d, PruneOptions{}, true); err != nil {
65: 		t.Fatal(err)
66: 	}
67: 	before := stack.inventoryJSON(api)
68: 	plan, err := Sync(ctx, api, d, false)
69: 	if err != nil {
70: 		t.Fatal(err)
71: 	}
72: 	if len(plan.Changes) == 0 || stack.inventoryJSON(api) != before {
73: 		t.Fatalf("dry run planned %d changes or mutated the manager", len(plan.Changes))
74: 	}
75: 	applied, err := Sync(ctx, api, d, true)
76: 	if err != nil {
77: 		t.Fatal(err)
78: 	}
79: 	t.Logf("first sync applied %d changes", len(applied.Changes))
80: 	if len(applied.Warnings) != 3 {
81: 		t.Fatalf("sync warnings: %v", applied.Warnings)
82: 	}
83: 	second, err := Sync(ctx, api, d, true)
84: 	if err != nil || len(second.Changes) != 0 {
85: 		t.Fatalf("second sync was not a no-op: %v %v", second.Changes, err)
86: 	}
87: 	stack.verifySynced(owner, d, seeded)
88: 	stack.verifyTraffic(owner, d, seeded)
89: 
90: 	// A network admin may not rename peers: prune needs the admin role.
91: 	if status := stack.status(networkAdmin, "PUT", "/peers/"+seeded.peers["ts-ops"],
92: 		map[string]any{"name": "ts-ops", "ssh_enabled": false, "login_expiration_enabled": false,
93: 			"inactivity_expiration_enabled": false}); status != http.StatusForbidden {
94: 		t.Fatalf("network_admin peer update returned HTTP %d, want 403", status)
95: 	}
96: 
97: 	// Replace db-1: the old revision goes offline, a new identity at the
98: 	// same slot IP registers under its OS hostname.
99: 	slot := d.Slots[3]
100: 	stack.removeContainer("gru-1-db-1")
101: 	stale := seeded.peers["gru-1-db-1"]
102: 	stack.wait("replaced revision to disconnect", 90*time.Second, func() bool {
103: 		var peer apiPeer
104: 		return stack.call(owner, "GET", "/peers/"+stale, nil, &peer) == nil && !peer.Connected
105: 	})
106: 	stack.client("ip-replacement", seeded.serverKey, slot.IP, false)
107: 	live := stack.peerID(owner, "ip-replacement")
108: 
109: 	pruned, err := Prune(ctx, api, d, PruneOptions{}, true)
110: 	if err != nil {
111: 		t.Fatal(err)
112: 	}
113: 	t.Logf("prune applied %v", pruned.Changes)
114: 	var peers []apiPeer
115: 	if err := stack.call(owner, "GET", "/peers", nil, &peers); err != nil {
116: 		t.Fatal(err)
117: 	}
118: 	if slices.ContainsFunc(peers, func(p apiPeer) bool { return p.ID == stale }) {
119: 		t.Fatal("prune kept the replaced revision")
120: 	}
121: 	index := slices.IndexFunc(peers, func(p apiPeer) bool { return p.ID == live })
122: 	if index < 0 || peers[index].Name != d.PeerName(slot) || !cleanLabel(peers[index], d.PeerName(slot)) {
123: 		t.Fatalf("live peer was not renamed to its slot name: %+v", peers[index])
124: 	}
125: 	if !slices.ContainsFunc(peers, func(p apiPeer) bool { return p.ID == seeded.peers["operator-1"] }) ||
126: 		!slices.ContainsFunc(peers, func(p apiPeer) bool { return p.ID == seeded.peers["gru-1-ctl-1"] }) {
127: 		t.Fatal("prune deleted a peer it must keep")
128: 	}
129: 	again, err := Prune(ctx, api, d, PruneOptions{}, true)
130: 	if err != nil || len(again.Changes) != 0 {
131: 		t.Fatalf("second prune was not a no-op: %v %v", again.Changes, err)
132: 	}
133: 
134: 	// Decommission ctl-1: prune keeps a down slot's last peer, so
135: 	// remove-peers deletes it once its server is gone.
