141: 	})
142: 	removed, err := Remove(ctx, api, d, []string{d.Slots[0].Name}, true)
143: 	if err != nil || len(removed.Changes) != 1 {
144: 		t.Fatalf("remove-peers: %v %v", removed.Changes, err)
145: 	}
