147: 		t.Fatal(err)
148: 	}
149: 	if slices.ContainsFunc(peers, func(p apiPeer) bool { return p.ID == controllerA }) ||
150: 		!slices.ContainsFunc(peers, func(p apiPeer) bool { return p.ID == live }) {
151: 		t.Fatal("remove-peers deleted the wrong peers")
152: 	}
153: 
154: 	// A fresh server setup key enrolls the slot's next server into the
155: 	// servers group only.
156: 	var fresh bytes.Buffer
157: 	if _, err := CreateServerSetupKey(ctx, api, d, &fresh, true); err != nil {
158: 		t.Fatal(err)
159: 	}
