38: func TestRemoteCommandStreamsLargeSocketInventory(t *testing.T) {
39: 	if _, err := exec.LookPath("jq"); err != nil {
40: 		t.Skip("remote command requires jq")
41: 	}
42: 	var s snapshot
43: 	if err := json.Unmarshal(observation(t, "10.250.10.155", nil), &s); err != nil {
