47: 	if err != nil {
48: 		t.Fatal(err)
49: 	}
50: 	wanted := strings.Repeat(s.Sockets+"\n", 2048)
51: 	if len(wanted) <= 128<<10 {
52: 		t.Fatal("fixture must exceed Linux's single-argument limit")
53: 	}
54: 	unrelated := strings.ReplaceAll(s.Sockets, `("netbird",pid=123,`, `("nginx",pid=456,`)
55: 	otherPID := strings.ReplaceAll(s.Sockets, "pid=123,", "pid=1234,")
56: 	dir := t.TempDir()
57: 	for name, body := range map[string][]byte{
58: 		"status.json": status,
59: 		"sockets.txt": []byte(strings.Repeat(unrelated+"\n", 4096) + otherPID + "\n" + wanted),
60: 	} {
61: 		if err := os.WriteFile(filepath.Join(dir, name), body, 0644); err != nil {
62: 			t.Fatal(err)
63: 		}
64: 	}
65: 	for name, body := range map[string]string{
66: 		"netbird":   `cat "$TS676_TEST_STATUS"`,
67: 		"systemctl": "printf '123\\n'",
68: 		"getent":    "printf '10.250.10.155 STREAM netbird.terrascale.tech\\n'",
69: 		"ss":        "cat \"$TS676_TEST_SOCKETS\"\nexit \"${TS676_TEST_SS_CODE:-0}\"",
70: 	} {
71: 		if err := os.WriteFile(filepath.Join(dir, name), []byte("#!/bin/sh\n"+body+"\n"), 0755); err != nil {
72: 			t.Fatal(err)
73: 		}
74: 	}
75: 	for _, ssCode := range []string{"0", "1"} {
76: 		command := exec.CommandContext(t.Context(), "sh", "-c", strings.Replace(RemoteCommand, "/usr/local/bin/netbird", "netbird", 1))
77: 		command.Env = append(os.Environ(), "PATH="+dir+string(os.PathListSeparator)+os.Getenv("PATH"),
78: 			"TS676_TEST_STATUS="+filepath.Join(dir, "status.json"), "TS676_TEST_SOCKETS="+filepath.Join(dir, "sockets.txt"), "TS676_TEST_SS_CODE="+ssCode)
79: 		body, err := command.Output()
80: 		if ssCode != "0" {
81: 			if err == nil {
82: 				t.Fatal("failed socket inventory produced a successful observation")
83: 			}
84: 			continue
85: 		}
86: 		if err != nil {
87: 			t.Fatal(err)
88: 		}
89: 		if err := inspect(body, netip.MustParseAddr("10.250.10.155")); err != nil {
90: 			t.Fatal(err)
91: 		}
92: 		if err := json.Unmarshal(body, &s); err != nil {
93: 			t.Fatal(err)
94: 		}
95: 		if strings.Contains(s.Sockets, "nginx") || strings.Contains(s.Sockets, "pid=1234,") || strings.Count(s.Sockets, "pid=123,") != 2048 {
96: 			t.Fatal("observation lost NetBird sockets or included unrelated processes")
97: 		}
98: 	}
99: }

